	}
	s, err := settings.Load(ctx)
	if err != nil {
		return nil, fmt.Errorf("load settings: %w", err)
	}
	if s != nil {
		if skills := s.ReviewSkillsFor(string(agentName)); len(skills) > 0 {
			return skills, nil
		}
	}
	return nil, nil
}

