// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)

// Refresh the entire/checkpoints/v1 branch before reading or writing
// when HEAD already references a checkpoint. Two concerns both require
// fresh state:
//
//  1. Conflict detection (review mode): a session already recorded in
//     the checkpoint — locally OR on the remote — must not be silently
//     overwritten. Without a fetch, a stale local branch makes the
//     sessionID-dedup check miss remote-only entries.
//  2. Correct append-as-next-session: findSessionIndex returns
//     len(Sessions) when the sessionID isn't already present. With a
//     stale local view, this returns a too-low index and collides
//     with an existing remote-only session on push.
//
// Mirror the fallback chain `entire resume` uses (getMetadataTree in
// resume.go): checkpoint-remote → treeless fetch → local → full fetch
// → remote-tracking ref. getMetadataTree returns a repo handle that's
// been re-opened after each fetch so go-git's packfile cache sees the
// new objects; reuse that fresh repo downstream.
if isExistingCheckpoint {
	if _, freshRepo, fetchErr := getMetadataTree(ctx); fetchErr == nil {
		repo = freshRepo
	} else {
		// Non-fatal: proceed with local state. The guard below can
		// only catch what's visible locally; on push the user may
		// still hit a conflict. Better than blocking attach on a
		// transient fetch failure.
		logging.Warn(logCtx, "failed to refresh metadata branch before attach; proceeding with local state",
			slog.String("error", fetchErr.Error()))
	}
}

