53	func scanPluginCache(ctx context.Context, root string) []agent.DiscoveredSkill {
54		entries, err := os.ReadDir(root)
55		if err != nil {
56			logging.Debug(ctx, "claude-code discovery: plugin cache unreadable",
57				slog.String("root", root), slog.String("error", err.Error()))
58			return nil
59		}
60		var found []agent.DiscoveredSkill
61		for _, marketEntry := range entries {
