103		if err != nil {
104			return nil
105		}
106		var found []agent.DiscoveredSkill
107		for _, skillEntry := range entries {
108			if !skillEntry.IsDir() {
109				continue
110			}
111			skillDir := filepath.Join(dir, skillEntry.Name())
112			skillFile := filepath.Join(skillDir, "SKILL.md")
113			data, err := os.ReadFile(skillFile) //nolint:gosec // G304: skillFile is constructed from a ReadDir walk under HOME, not user input
114			if err != nil {
115				continue
116			}
117			name, description, parseErr := parseSkillFrontmatter(data)
118			if parseErr != nil {
