125			}
126			invocation := invocationName(name, pluginName)
127			if !skilldiscovery.Matches(invocation, description) {
128				continue
129			}
130			found = append(found, agent.DiscoveredSkill{
131				Name:        invocation,
132				Description: description,
133				SourcePath:  skillFile,
134			})
135		}
136		return found
137	}
