139	// scanFlatMarkdownDir reads *.md files directly under dir (no nesting), parses
140	// their YAML frontmatter for `description:`, and derives the invocation name
141	// from the filename (stripping the .md suffix). Used for both plugin
142	// commands/agents and user-level ~/.claude/commands and ~/.claude/agents.
143	//
144	// Frontmatter shape differs from SKILL.md — no `name:` field, so the
145	// filename is the source of truth for the invocation name.
146	func scanFlatMarkdownDir(ctx context.Context, dir, pluginName string) []agent.DiscoveredSkill {
147		entries, err := os.ReadDir(dir)
148		if err != nil {
149			return nil
150		}
151		var found []agent.DiscoveredSkill
152		for _, entry := range entries {
153			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".md") {
154				continue
155			}
156			baseName := strings.TrimSuffix(entry.Name(), ".md")
157			if strings.EqualFold(baseName, "README") {
158				continue
159			}
160			filePath := filepath.Join(dir, entry.Name())
161			data, err := os.ReadFile(filePath) //nolint:gosec // G304: filePath is constructed from a ReadDir walk under HOME, not user input
162			if err != nil {
163				continue
164			}
165			_, description, parseErr := parseSkillFrontmatter(data)
166			if parseErr != nil {
167				logging.Debug(ctx, "claude-code discovery: skipping malformed command/agent",
168					slog.String("path", filePath), slog.String("error", parseErr.Error()))
169				continue
170			}
171			invocation := invocationName(baseName, pluginName)
172			if !skilldiscovery.Matches(invocation, description) {
173				continue
174			}
175			found = append(found, agent.DiscoveredSkill{
176				Name:        invocation,
177				Description: description,
178				SourcePath:  filePath,
179			})
180		}
181		return found
182	}
