184	// invocationName builds the slash-prefixed invocation form. Plugin-prefixed
185	// names use "/plugin:name"; bare names use "/name".
186	func invocationName(name, pluginName string) string {
187		if pluginName == "" {
188			return "/" + name
189		}
190		return "/" + pluginName + ":" + name
