192	
193	// parseSkillFrontmatter extracts `name:` and `description:` from a minimal
194	// YAML frontmatter block. Purpose-built for the tiny subset of YAML these
195	// SKILL.md / command / agent files actually use.
196	//
197	// Trims surrounding double-quotes from values so `description: "foo bar"`
198	// is returned as `foo bar` — the command/agent frontmatter quotes values;
199	// SKILL.md files usually don't.
200	func parseSkillFrontmatter(data []byte) (name, description string, err error) {
201		s := string(data)
202		if !strings.HasPrefix(s, "---\n") && !strings.HasPrefix(s, "---\r\n") {
203			return "", "", errors.New("no frontmatter delimiter")
204		}
205		body := strings.TrimPrefix(strings.TrimPrefix(s, "---\r\n"), "---\n")
206		end := strings.Index(body, "\n---")
207		if end < 0 {
208			return "", "", errors.New("no closing frontmatter delimiter")
209		}
210		for _, line := range strings.Split(body[:end], "\n") {
211			line = strings.TrimSpace(line)
212			switch {
213			case strings.HasPrefix(line, "name:"):
214				name = strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "name:")), `"`)
215			case strings.HasPrefix(line, "description:"):
216				description = strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "description:")), `"`)
217			}
218		}
219		return name, description, nil
220	}
