func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	// Read existing summary to get current session count
	var existingSummary *CheckpointSummary
	metadataPath := basePath + paths.MetadataFileName
	_, metadataEntryExists := entries[metadataPath]
	if entry, exists := entries[metadataPath]; exists {
		existing, err := s.readSummaryFromBlob(entry.Hash)
		if err == nil {
			existingSummary = existing
		} else {
			logging.Debug(ctx, "writeStandardCheckpointEntries: readSummaryFromBlob failed",
				slog.String("metadata_path", metadataPath),
				slog.String("error", err.Error()))
		}
	}

	// TEMP DEBUG: diagnose "review-attach overwrote session 0" report.
	// Remove once root-caused.
	{
		sessionsLen := 0
		if existingSummary != nil {
			sessionsLen = len(existingSummary.Sessions)
		}
		entryKeys := make([]string, 0, len(entries))
		for k := range entries {
			if strings.HasPrefix(k, basePath) {
				entryKeys = append(entryKeys, k)
			}
		}
		sort.Strings(entryKeys)
		logging.Info(ctx, "DEBUG writeStandardCheckpointEntries",
			slog.String("base_path", basePath),
			slog.String("write_session_id", opts.SessionID),
			slog.String("checkpoint_id", opts.CheckpointID.String()),
			slog.Bool("metadata_entry_exists", metadataEntryExists),
			slog.Bool("existing_summary_nil", existingSummary == nil),
			slog.Int("existing_sessions_len", sessionsLen),
			slog.Int("entries_count_under_base", len(entryKeys)),
			slog.Any("entries_keys", entryKeys))
	}

	// Determine session index: reuse existing slot if session ID matches, otherwise append
	sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)

	logging.Info(ctx, "DEBUG findSessionIndex result",
		slog.Int("session_index", sessionIndex),
		slog.String("write_session_id", opts.SessionID))

