306	func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
307		// Read existing summary to get current session count
308		var existingSummary *CheckpointSummary
309		metadataPath := basePath + paths.MetadataFileName
310		if entry, exists := entries[metadataPath]; exists {
311			existing, err := s.readSummaryFromBlob(entry.Hash)
312			if err == nil {
313				existingSummary = existing
314			}
315		}
316	
317		// Determine session index: reuse existing slot if session ID matches, otherwise append
318		sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
319	
320		// Capture any pre-existing session-0 metadata before writeSessionToSubdirectory
321		// clears that subtree. The warning below only fires in the suspicious shape
322		// where findSessionIndex chose slot 0 but the tree already had session-0
323		// metadata for a different session — typically meaning the root summary is
324		// missing/stale while a numbered session subdir still exists.
325		var existingSessionZeroMeta *CommittedMetadata
326		if sessionIndex == 0 {
327			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
328				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil {
329					existingSessionZeroMeta = existingMeta
330				}
331			}
332		}
333	
334		// Write session files to numbered subdirectory
335		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
336		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
337		if err != nil {
338			return err
339		}
340	
341		// Copy additional metadata files from directory if specified (to session subdirectory)
342		if opts.MetadataDir != "" {
343			if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
344				return fmt.Errorf("failed to copy metadata directory: %w", err)
345			}
346		}
347	
348		// Build the sessions array
349		var sessions []SessionFilePaths
350		if existingSummary != nil {
351			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
352			copy(sessions, existingSummary.Sessions)
353		} else {
354			sessions = make([]SessionFilePaths, 1)
355		}
356		sessions[sessionIndex] = sessionFilePaths
357	
358		// Tripwire: if we're writing session 0 and there was already session-0
359		// metadata for a DIFFERENT session ID, emit a loud warning. This is a
360		// tree-corruption / stale-summary shape, not a routine overwrite path.
361		if existingSessionZeroMeta != nil && existingSessionZeroMeta.SessionID != opts.SessionID {
362			logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
363				slog.String("checkpoint_id", opts.CheckpointID.String()),
364				slog.String("existing_session_id", existingSessionZeroMeta.SessionID),
365				slog.String("write_session_id", opts.SessionID),
366				slog.Bool("existing_summary_nil", existingSummary == nil))
367		}
368	
369		// Update root metadata.json with CheckpointSummary
370		return s.writeCheckpointSummary(opts, basePath, entries, sessions)
371	}
