373	// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
374	// Returns the absolute file paths from the git tree root for the sessions map.
375	func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
376		filePaths := SessionFilePaths{}
377	
378		// Clear any existing entries at this path so stale files from a previous
379		// write (e.g. prompt.txt) don't persist on overwrite.
380		for key := range entries {
381			if strings.HasPrefix(key, sessionPath) {
382				delete(entries, key)
383			}
384		}
385	
386		// Write transcript
387		wroteTranscript, err := s.writeTranscript(ctx, opts, sessionPath, entries)
388		if err != nil {
389			return filePaths, err
390		}
391		if wroteTranscript {
392			filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
393			filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
394		}
