571	func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
572		if existingSummary == nil {
573			return 0
574		}
575		for i := range len(existingSummary.Sessions) {
576			path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
577			if entry, exists := entries[path]; exists {
578				meta, err := s.readMetadataFromBlob(entry.Hash)
579				if err != nil {
580					logging.Warn(ctx, "failed to read session metadata during dedup check",
581						slog.Int("session_index", i),
582						slog.String("session_id", sessionID),
583						slog.String("error", err.Error()),
584					)
585					continue
586				}
587				if meta.SessionID == sessionID {
588					return i
589				}
590			}
591		}
592		return len(existingSummary.Sessions)
593	}
