595	// reaggregateFromEntries reads all session metadata from the entries map and
596	// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
597	func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
598		var totalCount int
599		var allFiles []string
600		var totalTokens *agent.TokenUsage
601	
602		for i := range sessionCount {
603			path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
604			entry, exists := entries[path]
605			if !exists {
606				return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
607			}
608			meta, err := s.readMetadataFromBlob(entry.Hash)
609			if err != nil {
610				return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
611			}
612			totalCount += meta.CheckpointsCount
613			allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
614			totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
615		}
616	
617		return totalCount, allFiles, totalTokens, nil
618	}
