620	// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
621	func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
622		blob, err := repo.BlobObject(hash)
623		if err != nil {
624			return nil, fmt.Errorf("failed to get blob: %w", err)
625		}
626	
627		reader, err := blob.Reader()
628		if err != nil {
629			return nil, fmt.Errorf("failed to get blob reader: %w", err)
630		}
631		defer reader.Close()
632	
633		var result T
634		if err := json.NewDecoder(reader).Decode(&result); err != nil {
635			return nil, fmt.Errorf("failed to decode: %w", err)
636		}
637	
638		return &result, nil
639	}
